		if (id_hi == 0x3f && id_lo == 0x0) {
			apdu.p1 = 0x0;
			apdu.p2 = 0x0C;
			apdu.le = 0;
			apdu.resplen = 0;
			apdu.resp = NULL;
			apdu.cse = SC_APDU_CASE_3_SHORT;
			isMF = 1;
		} else if (file_out || is_file) {
			// last component (i.e. file or path)
			apdu.p1 = 0x2;
