				sc_log(card->ctx, "Too many options in OpenSC Info file");
				r = SC_ERROR_PKCS15INIT;
				goto error;
			}
			r = set_info_string(&profile->options[nopts], p, n);
			if (r < 0)
				goto error;
			profile->options[++nopts] = NULL;
